struct Point {
  int x;
  int y;
};

typedef struct Point Point;

int sum_point(struct Point p) {
  return p.x + p.y;
}

int compute(void) {
  struct Point a = (struct Point){1, 2};
  int total = sum_point((struct Point){.x = 3, .y = 4});
  Point b = (Point){.y = 5};
  total += a.x + b.y;
  return total;
}

int main(void) {
  return compute();
}

